function usaFirmaAutografa(){
  const chk = document.getElementById("chk-firma-autografa");
  if(chk) return chk.checked;
  return localStorage.getItem("fc_firma_autografa") !== "false";
}
function salvaPrefFirma(attivo){
  localStorage.setItem("fc_firma_autografa", attivo ? "true" : "false");
}
function initPrefFirma(){
  const chk = document.getElementById("chk-firma-autografa");
  if(chk){
    chk.checked = localStorage.getItem("fc_firma_autografa") !== "false";
  }
}

